// rust-ts contract declarations (lane clippy-contract-a; not a port of an upstream file) for two modules this branch cannot have yet:
// - `src/clippy_config/lib.ts` belongs to the parallel lane clippy-contract-b;
// - `src/clippy_lints/lib.gen.ts` is written by `bun tools/codegen/clippy.ts` only once every module it imports exists, which
//   includes clippy_config/lib.ts (root decision "codegen-clippy-macros (D5)"); root writes it at integration.
// These ambient blocks declare exactly what clippy-contract-a's files use from them, so they type-check now (the pattern of codegen-fmt-serde's src/rustfmt/contract.gen.d.ts):
// TypeScript consults a block only while no file resolves the import, so once clippy_config/lib.ts lands, the real module is
// checked against the same uses, and its block is deleted (root, at integration; the file once both have landed).
// A block is named by the exact specifier text plus `*` (TypeScript needs the `*` to accept a relative-looking name). Only an
// import written exactly so matches; contract.test.ts checks that every import of a declared specifier resolves to
// the declared module from the importing file, so no block hides a wrong path.
//
// What clippy-contract-b must export from src/clippy_config/lib.ts (`pub use conf::{Conf, sanitize_explanation};
// pub use metadata::ConfMetadata;`, clippy_config/src/lib.rs):
// - `Conf`, a class: `static load(sess: Session): Conf` (conf.rs:935, `&'static Conf`) and `static get_metadata(): ConfMetadata[]`
//   (define_Conf!'s conf.rs:130; generated by the follow-up batch codegen-clippy-conf);
// - `sanitize_explanation(raw_docs: string): string` (conf.rs:836);
// - `ConfMetadata` (metadata.rs:4) with `lints: readonly string[]`, and its `Display` as `display_ConfMetadata(v): string` (metadata.rs:12).

declare module "../clippy_config/lib.ts*" {
  export class Conf {
    static load(sess: import("../rustc_session/session.ts").Session): Conf;
    static get_metadata(): ConfMetadata[];
  }
  export function sanitize_explanation(raw_docs: string): string;
  export interface ConfMetadata {
    name: string;
    default: string;
    lints: readonly string[];
    doc: string;
    renamed_to: string | undefined;
  }
  export function display_ConfMetadata(v: ConfMetadata): string;
}

declare module "../../clippy_config/lib.ts*" {
  export type Conf = import("../clippy_config/lib.ts").Conf;
}

// The two combined passes (lib.gen.ts, expanded from lib.rs:492 and :553), as lib.ts uses them.
declare module "./lib.gen.ts*" {
  type Conf = import("../clippy_config/lib.ts").Conf;
  type FormatArgsStorage = import("../clippy_utils/macros.ts").FormatArgsStorage;
  type AttrStorage = import("./utils/attr_collector.ts").AttrStorage;
  type LintVec = import("../rustc_lint_defs/lib.ts").LintVec;
  export class CombinedEarlyLintPass implements import("../rustc_lint/passes.ts").EarlyLintPass {
    static new(conf: Conf, format_args: FormatArgsStorage, attrs: AttrStorage): CombinedEarlyLintPass;
    name(): string;
    get_lints(): LintVec;
  }
  export class CombinedLateLintPass implements import("../rustc_lint/passes.ts").LateLintPass {
    static new(
      tcx: import("../rustc_middle/ty/context.ts").TyCtxt,
      conf: Conf,
      format_args: FormatArgsStorage,
      attrs: AttrStorage,
      is_active: (lints: LintVec) => boolean,
    ): CombinedLateLintPass;
    name(): string;
    get_lints(): LintVec;
  }
}
